#!/usr/bin/env node
/**
 * Pre-publish guards for the dsh bundle.
 *
 * Two failure classes matter here, and neither shows up as a build error:
 * a patch row or export that names a file the tarball does not ship, which
 * breaks at resolution time on a user's machine; and a missing or malformed
 * `skills/`, which arrives through the CI sync from apify-plugins-internal
 * rather than being authored here.
 */
import { execFileSync } from 'node:child_process'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const failures = []
const check = (ok, message) => { if (!ok) failures.push(message) }
// npm names may contain `.`, which is a regex metacharacter.
const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// ── manifest ────────────────────────────────────────────────────────────────

// Without dsh.bundle.patch, `dsh plugin add` installs a plain dependency and
// activates no layer, with only a warning.
const patchPath = pkg.dsh?.bundle?.patch
check(typeof patchPath === 'string', 'package.json must declare dsh.bundle.patch')
check(pkg.files?.includes('cordis.patch.yml'), 'files[] must ship cordis.patch.yml')

// An install-time build would put pnpm's allowBuilds prompt between the user
// and a working plugin.
for (const script of ['prepare', 'postinstall', 'install']) {
  check(!pkg.scripts?.[script], `package.json must not define a "${script}" script (triggers pnpm allowBuilds)`)
}

// ── patch rows ──────────────────────────────────────────────────────────────

const patchText = existsSync(join(root, 'cordis.patch.yml'))
  ? readFileSync(join(root, 'cordis.patch.yml'), 'utf8')
  : ''
const activeLines = patchText.split('\n').filter((line) => !/^\s*#/.test(line)).join('\n')

for (const id of ['apify-mcp', 'apify-skills']) {
  check(new RegExp(`^\\s*(-\\s*)?id:\\s*${id}\\s*$`, 'm').test(activeLines), `cordis.patch.yml is missing the "${id}" row`)
}

// A rename that misses this file leaves a bundle that installs and then fails
// to resolve its own module.
const moduleRow = `${pkg.name}/mount-skills`
check(
  activeLines.includes(moduleRow),
  `cordis.patch.yml does not reference "${moduleRow}" — package renamed without updating the patch?`,
)
// Every row naming this package must resolve to a declared export.
for (const match of activeLines.matchAll(new RegExp(`${escapeRegExp(pkg.name)}(/[\\w./-]+)?`, 'g'))) {
  const subpath = match[1] ? `.${match[1]}` : '.'
  check(pkg.exports?.[subpath] !== undefined, `patch names ${match[0]}, which is not a declared export (${subpath})`)
}

// ── skills (generated by the sync) ──────────────────────────────────────────

const skillsDir = join(root, 'skills')
if (!existsSync(skillsDir)) {
  failures.push('skills/ is missing — run the apify-plugins-internal sync before publishing')
} else {
  const skills = readdirSync(skillsDir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && existsSync(join(skillsDir, e.name, 'SKILL.md')))
    .map((e) => e.name)
  check(skills.length > 0, 'skills/ contains no <name>/SKILL.md directories')
  check(skills.includes('apify'), 'skills/apify (the router) is missing')

  // dsh drops a skill whose frontmatter name is not kebab-case, with only a
  // runtime log warning.
  for (const name of skills) {
    const front = /^---\s*\n([\s\S]*?)\n---/.exec(readFileSync(join(skillsDir, name, 'SKILL.md'), 'utf8'))
    const declared = front && /^name:\s*(.+)$/m.exec(front[1])?.[1].trim()
    check(Boolean(declared), `skills/${name}/SKILL.md has no frontmatter name`)
    if (declared) {
      check(
        /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(declared),
        `skills/${name}/SKILL.md name "${declared}" is not kebab-case — dsh would drop the skill`,
      )
    }
  }
}

// ── the actual tarball ──────────────────────────────────────────────────────

const packed = JSON.parse(
  execFileSync('npm', ['pack', '--dry-run', '--json', '--ignore-scripts'], { cwd: root, encoding: 'utf8' }),
)
const shipped = new Set(packed[0].files.map((file) => file.path))

// A declared export missing from the tarball is a runtime failure on a user's
// machine, not a failure here.
for (const [subpath, target] of Object.entries(pkg.exports ?? {})) {
  for (const path of (typeof target === 'string' ? [target] : Object.values(target))) {
    const file = path.replace(/^\.\//, '')
    check(shipped.has(file), `export "${subpath}" points at ${file}, which is not in the tarball`)
  }
}
for (const file of ['cordis.patch.yml', 'LICENSE', 'README.md', 'skills/apify/SKILL.md']) {
  check(shipped.has(file), `${file} is not in the tarball`)
}
for (const path of shipped) {
  check(!path.startsWith('scripts/') && !path.startsWith('.github/'), `${path} should not ship`)
}

if (failures.length > 0) {
  for (const failure of failures) process.stderr.write(`verify-bundle: ${failure}\n`)
  process.exit(1)
}
process.stdout.write(
  `verify-bundle: ok (${shipped.size} files, ${(packed[0].unpackedSize / 1024).toFixed(1)} kB unpacked)\n`,
)
